import React, { useState } from "react";

const Quiz = ({ onSubmit }) => {
  const [style, setStyle] = useState("");
  const [occasion, setOccasion] = useState("");
  const [item, setItem] = useState("");

  const handleSubmit = (e) => {
    e.preventDefault();
    onSubmit({ style, occasion, item });
  };

  const items = ["jeans", "skirt", "dress", "jacket", "blazer", "trousers"];

  return (
    <form onSubmit={handleSubmit} style={{ maxWidth: "400px", margin: "0 auto", textAlign: "left" }}>
      <h1>👗 MyStyleDNA Quiz</h1>

      {/* Style Dropdown */}
      <label>✨ What style speaks to you?</label>
      <select value={style} onChange={(e) => setStyle(e.target.value)} required>
        <option value="">-- Choose Style --</option>
        <option value="Modern Classic">Modern Classic</option>
        <option value="Boho Chic">Boho Chic</option>
        <option value="Streetwear">Streetwear</option>
        <option value="Minimalist">Minimalist</option>
        <option value="Vintage">Vintage</option>
      </select>

      <br /><br />

      {/* Occasion Dropdown */}
      <label>🎯 What is the occasion?</label>
      <select value={occasion} onChange={(e) => setOccasion(e.target.value)} required>
        <option value="">-- Choose Occasion --</option>
        <option value="Work">Work</option>
        <option value="Vacation">Vacation</option>
        <option value="Festive">Festive</option>
        <option value="Casual">Casual</option>
        <option value="Party">Party</option>
        <option value="Street">Street</option>
        <option value="Formal">Formal</option>
      </select>

      <br /><br />

      {/* Item Buttons */}
      <label>👕 Choose a clothing item:</label>
      <div style={{ display: "flex", flexWrap: "wrap", gap: "10px", marginTop: "10px" }}>
        {items.map((itm) => (
          <button
            type="button"
            key={itm}
            onClick={() => setItem(itm)}
            style={{
              padding: "8px 12px",
              borderRadius: "6px",
              border: item === itm ? "2px solid #333" : "1px solid #ccc",
              backgroundColor: item === itm ? "#ddd" : "#f9f9f9",
              cursor: "pointer",
            }}
          >
            {itm.charAt(0).toUpperCase() + itm.slice(1)}
          </button>
        ))}
      </div>

      <br />
      <button
        type="submit"
        disabled={!style || !occasion || !item}
        style={{ padding: "10px 20px", borderRadius: "6px", border: "1px solid #ccc", backgroundColor: "#f0f0f0", marginTop: "20px" }}
      >
        Show My Style
      </button>
    </form>
  );
};

export default Quiz;
